// ---- Реестр планов ----
// trainingWeekdays — в какие дни недели по плану тренировка (как у Date.getDay():
// 0 — воскресенье, 1 — понедельник … 6 — суббота). По ним считаются серия дней
// (множитель XP), недельная серия, «Первая неделя» и напоминание о пропуске: день
// отдыха по плану без тренировки ничего не рвёт. У плана на 4 дня будет, например,
// [1, 2, 4, 5] — и среда с субботой перестанут считаться пропусками.
export const PLANS = [
  {
    id: 'plan1',
    title: 'Сила, кардио, бассейн',
    description: 'Три силовых, два кардио на дорожке и бассейн · 4 недели × 6 дней',
    daysPerWeek: 6,
    trainingWeekdays: [1, 2, 3, 4, 5, 6], // ПН–СБ
    weekLabels: { 1: 'База', 2: 'Объём', 3: 'Интенсив', 4: 'Разгрузка' },
    days: PLAN1_DAYS,
  },
  {
    id: 'plan2',
    title: 'Сплит 6 дней',
    description: 'Шесть силовых ПН–СБ с кардио-финишером · 4 недели',
    daysPerWeek: 6,
    trainingWeekdays: [1, 2, 3, 4, 5, 6], // ПН–СБ
    weekLabels: { 1: 'База', 2: 'Объём', 3: 'Тяжёлая', 4: 'Разгрузка' },
    days: PLAN2_DAYS,
    // Прежние варианты дней: тренировки ДО даты before сверяются с ними (planDayAt).
    // По возрастанию before: берётся первый вариант, чья граница позже даты тренировки.
    history: [
      { before: '2026-10-30', days: PLAN2_BEFORE_2026_10_30 },
      { before: '2026-11-02', days: PLAN2_2026_10_30 },
      { before: '2026-11-11', days: PLAN2_2026_11_02 },
    ],
  },
];

// План по умолчанию — старый: у всех профилей и тренировок до 1.1.0 он и был.
// Новый план включается вручную в «Профиле».
export const DEFAULT_PLAN_ID = 'plan1';

// Свои планы пользователя (src/userPlans.js): App кладёт их сюда при загрузке, и весь
// движок находит их через getPlan так же, как встроенные. Удалённые (hidden) тоже
// здесь: по ним есть прошлые тренировки, хотя в списке выбора их уже нет.
let userPlans = [];
export function setUserPlans(list) { userPlans = list || []; }
export const isUserPlanId = (id) => String(id || '').startsWith('u-');

export function getPlan(planId) {
  return userPlans.find((p) => p.id === planId)
    || PLANS.find((p) => p.id === planId)
    || PLANS.find((p) => p.id === DEFAULT_PLAN_ID);
}

// Дни недели в своём плане — кодами: номера у всех свои, а 0 — воскресенье только у Date.
// Индекс — как у Date.getDay().
export const WEEKDAY_CODES = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];
export const weekdayNumbers = (codes) => (codes || [])
  .map((c) => WEEKDAY_CODES.indexOf(c))
  .filter((n) => n >= 0);

export const DEFAULT_TRAINING_WEEKDAYS = [1, 2, 3, 4, 5, 6];

export function trainingWeekdaysOf(planId) {
  const plan = getPlan(planId);
  return (plan && Array.isArray(plan.trainingWeekdays) && plan.trainingWeekdays.length)
    ? plan.trainingWeekdays : DEFAULT_TRAINING_WEEKDAYS;
}

// «Тренировочный ли день по плану» с учётом смены плана. День относится к плану
// последней тренировки в этот день или раньше (до первой тренировки — к плану
// первой); после последней тренировки — к плану из профиля: его могли сменить
// уже после неё. Возвращает функцию (iso) => boolean.
export function makeTrainingDayCheck(sessions, currentPlanId) {
  const list = (sessions || [])
    .filter((x) => x && x.date)
    .map((x) => ({ date: x.date, planId: x.planId || DEFAULT_PLAN_ID }))
    .sort((a, b) => a.date.localeCompare(b.date));
  const lastDate = list.length ? list[list.length - 1].date : null;
  const cache = new Map();
  return (iso) => {
    if (cache.has(iso)) return cache.get(iso);
    let planId = currentPlanId || DEFAULT_PLAN_ID;
    if (lastDate && iso <= lastDate) {
      planId = list[0].planId;
      for (const x of list) { if (x.date <= iso) planId = x.planId; else break; }
    }
    const [y, m, d] = iso.split('-').map(Number);
    const weekday = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
    const res = trainingWeekdaysOf(planId).includes(weekday);
    cache.set(iso, res);
    return res;
  };
}

export function getPlanDay(planId, dayNum) {
  return getPlan(planId).days.find((d) => d.day === dayNum) || null;
}

// День плана в том виде, каким он был на дату date (план правили — см. history).
// Для истории: отчёты, «идеальные» тренировки. Без даты — текущий вариант.
export function planDayAt(planId, dayNum, date) {
  const plan = getPlan(planId);
  const old = date ? (plan.history || []).find((h) => date < h.before) : null;
  return (old ? old.days : plan.days).find((d) => d.day === dayNum) || null;
}

// Неделя программы (1..4) для дня цикла.
export function planWeekOf(plan, dayNum) {
  const per = (plan && plan.daysPerWeek) || 6;
  return Math.floor((dayNum - 1) / per) + 1;
}

// Следующий день после последнего сделанного. 0 — «план только что выбран»,
// начинаем с первого дня; после последнего дня цикла — снова первый.
// null/undefined — день не подставляем вообще (новый пользователь сам выбирает).
export function nextPlanDay(plan, lastDay) {
  if (lastDay == null) return null;
  const n = Number(lastDay) || 0;
  if (n < 1 || n >= plan.days.length) return 1;
  return n + 1;
}
